export const introHtml = '<p>Select the characters you need below, then download a ready-to-use file. The file teaches your system how to type those characters via the Compose key — for example, pressing <kbd class="mf-key">Compose</kbd> <kbd class="mf-key">:</kbd> <kbd class="mf-key">o</kbd> produces <strong>ö</strong>.</p>\n<p>It works on Linux and other Unix-like systems running X11 or Wayland (via XWayland or a compatible IBus/Fcitx Compose implementation) — just place the file at <code>~/.XCompose</code> (when using IBus, <code>~/.config/ibus/Compose</code> location is preferred) and restart your session (<kbd>ibus restart</kbd> or <kbd>fcitx5-remote -r</kbd>) for it to take effect.</p>\n';
